import { prisma } from "@/lib/prisma";
export default async function Attendance(){const data=await prisma.attendance.findMany({include:{student:true},orderBy:{date:"desc"}});return <main className="shell"><a href="/">← Dashboard</a><h1>Attendance</h1><div className="tableWrap"><table><thead><tr><th>Student</th><th>Date</th><th>Status</th></tr></thead><tbody>{data.map(a=><tr key={a.id}><td>{a.student.name}</td><td>{a.date.toLocaleDateString()}</td><td>{a.status}</td></tr>)}</tbody></table></div></main>}